-- Additive catalog only. Does not grant permissions or modify existing MFA requirements.
MERGE INTO M01_IAM_PERMISSION P USING (SELECT 'ACCOUNT_APPROVE' CODE FROM DUAL) S ON (P.PERMISSION_CODE=S.CODE) WHEN NOT MATCHED THEN INSERT (PERMISSION_ID,PERMISSION_CODE,RESOURCE_CODE,ACTION_CODE) VALUES (LOWER(RAWTOHEX(SYS_GUID())),S.CODE,'ACCOUNT',S.CODE);
